package golangjwt_test

import (
	"errors"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/golang-jwt/jwt/v5"

	golangjwt "github.com/gopernicus/gopernicus/integrations/cryptids/golang-jwt"
)

func TestLegacySDKToken(t *testing.T) {
	// Captured from the retired SDK, not generated by this adapter. The
	// fixture's README records the exact key, dates, and generation provenance.
	data, err := os.ReadFile("testdata/legacy-hs256.jwt")
	if err != nil {
		t.Fatal(err)
	}
	const legacySecret = "test-secret-key-at-least-32-chars-long"
	signer, err := golangjwt.New(legacySecret)
	if err != nil {
		t.Fatal(err)
	}
	token := strings.TrimSpace(string(data))
	claims, err := signer.Verify(token)
	if err != nil {
		t.Fatalf("Verify legacy SDK token: %v", err)
	}
	for key, want := range map[string]any{
		"user_id": "u123", "session_id": "s456",
		"iat": float64(1577836800), "exp": float64(4102444800),
	} {
		if claims[key] != want {
			t.Errorf("%s = %v, want %v", key, claims[key], want)
		}
	}
	if _, err := newSigner(t).Verify(token); err == nil {
		t.Fatal("legacy token verified with a different key")
	}
}

func TestUpstreamInteroperability(t *testing.T) {
	for _, method := range []*jwt.SigningMethodHMAC{jwt.SigningMethodHS256, jwt.SigningMethodHS384, jwt.SigningMethodHS512} {
		t.Run(method.Alg(), func(t *testing.T) {
			signer := newSigner(t, golangjwt.WithMethod(method))
			expiresAt := time.Now().Add(time.Hour)
			token, err := signer.Sign(map[string]any{"user_id": "u123"}, expiresAt)
			if err != nil {
				t.Fatalf("Sign: %v", err)
			}
			parsed, err := jwt.Parse(token, func(*jwt.Token) (any, error) {
				return []byte(testSecret), nil
			}, jwt.WithValidMethods([]string{method.Alg()}), jwt.WithExpirationRequired(), jwt.WithIssuedAt(), jwt.WithStrictDecoding())
			if err != nil {
				t.Fatalf("upstream verification: %v", err)
			}
			claims := parsed.Claims.(jwt.MapClaims)
			if claims["user_id"] != "u123" || claims["exp"] != float64(expiresAt.Unix()) {
				t.Errorf("unexpected upstream claims: %v", claims)
			}

			upstreamToken := signRaw(t, method, []byte(testSecret), jwt.MapClaims{
				"user_id": "u456", "exp": expiresAt.Unix(), "iat": time.Now().Unix(),
			})
			verified, err := signer.Verify(upstreamToken)
			if err != nil {
				t.Fatalf("Verify upstream token: %v", err)
			}
			if verified["user_id"] != "u456" || verified["exp"] != float64(expiresAt.Unix()) {
				t.Errorf("unexpected adapter claims: %v", verified)
			}
		})
	}
}

func TestSignerTokenVerifiesUnderLegacyRing(t *testing.T) {
	const secret = "test-secret-key-at-least-32-chars-long"
	signer, err := golangjwt.New(secret)
	if err != nil {
		t.Fatal(err)
	}
	fixture, err := os.ReadFile("testdata/legacy-hs256.jwt")
	if err != nil {
		t.Fatal(err)
	}
	tokens := map[string]string{"New": mustSign(t, signer), "testdata": strings.TrimSpace(string(fixture))}
	keys := map[string][]byte{"legacy": []byte(secret), "k1": ringKey1}

	ring := newRing(t, "k1", keys, golangjwt.WithLegacyKeyID("legacy"))
	for name, token := range tokens {
		claims, err := ring.Verify(token)
		if err != nil {
			t.Fatalf("%s token under a legacy ring: %v", name, err)
		}
		if claims["user_id"] == nil {
			t.Errorf("%s token claims = %v", name, claims)
		}
		if _, err := newRing(t, "k1", keys).Verify(token); !errors.Is(err, golangjwt.ErrMissingKeyID) {
			t.Errorf("%s token without the legacy option err = %v, want ErrMissingKeyID", name, err)
		}
	}

	// A kid=k2 token is refused by a ring holding only k1; the error names the
	// id, never the key.
	_, err = ring.Verify(signWithHeader(t, jwt.SigningMethodHS256, ringKey2, map[string]any{"kid": "k2"}))
	if !errors.Is(err, golangjwt.ErrUnknownKeyID) || !strings.Contains(err.Error(), `"k2"`) || strings.Contains(err.Error(), string(ringKey2)) {
		t.Fatalf("kid=k2 err = %v", err)
	}
}
